```C++
#include<iostream>

int main() {
    int n=8;
    int t1 = 0, t2 = 1, nextTerm = 0;

    for (int i = 1; i <= n; ++i) {
        if(i == 1) {
            std::cout << t1 << ", ";
            continue;
        }
        if(i == 2) {
            std::cout << t2 << ", ";
            continue;
        }
        nextTerm = t1 + t2;
        t1 = t2;
        t2 = nextTerm;
        if(i<n) std::cout << nextTerm << ", ";
        else std::cout << nextTerm;
    }
    return 0;
}
```

