#include <iostream>

void produce_sequence(int n) {
    for(int i = 1; i <= n; i++) {
        std::cout << i << ", " << i << ", ";
        if(i % 2 == 0)
            std::cout << i * 2 << ", " << i << ", ";
        else
            std::cout << i * 2 << ", ";
    }
}

int main() {
    produce_sequence(5);
    return 0;
}
