```cpp
#include <iostream>
#include <string>

std::string countAndSay(int n) {
    if (n == 0) return "";
    std::string res = "1";
    while (--n) {
        std::string cur = "";
        for (int i = 0; i < res.size(); i++) {
            int count = 1;
            while ((i + 1 < res.size()) && (res[i] == res[i + 1])) {
                i++;
                count++;
            }
            cur += std::to_string(count) + res[i];
        }
        res = cur;
    }
    return res;
}

int main() {
    for (int i = 1; i <= 8; i++) {
        std::cout << countAndSay(i) << std::endl;
    }
    return 0;
}
```

