#include<string>
using namespace std;

string nextNumber(string str) {
    string result = "";
    int i = 0;

    while (i < str.size()) {
        int count = 1;
        while ((i + 1) < str.size() && str[i] == str[i+1]) {
            i++;
            count++;    
        }
        result += to_string(count) + str[i];
        i++;
    }

    return result;
}

int main() {
    string str = "1";
    for (int i = 0; i < 10; i++) {
        cout << str << endl;
        str = nextNumber(str);
    }
    return 0;
}
