#include <iostream>
#include <string>

std::string nextNumber(std::string num) {
    std::string result = "";
    char countNum = num[0];
    int count = 1;
    for (int i = 1; i < num.size(); i++) {
        if (num[i] == countNum) {
            count++;
        } else {
            result += std::to_string(count) + countNum;
            countNum = num[i];
            count = 1;
        }
    }
    result += std::to_string(count) + countNum;
    return result;
}

int main() {
    std::string num = "1";
    for (int i = 0; i < 8; i++) {
        std::cout << num << std::endl;
        num = nextNumber(num);
    }
    return 0;
}
