```C++
#include<iostream>
using namespace std;

bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i = i + 6)
        if (n % i == 0 || n % (i + 2) == 0)
            return false;
    return true;
}

int main() {
    int arr[] = {2, 3, 5, 11, 23, 29, 41, 53, 83, 89, 113, 131};
    int size = sizeof(arr) / sizeof(arr[0]);
    for (int i = 0; i < size; i++) {
        if (isPrime(arr[i]))
            cout << arr[i] << " ";
    }
    return 0;
}
