function look_and_say_sequence()
    sequence = '1';

    for i=1:7
        disp(sequence)
        sequence = look_and_say(sequence);
    end
    disp(sequence)
end

function next_sequence = look_and_say(sequence)
    next_sequence = '';
    i = 1;

    while i <= length(sequence)
        count = 1;

        while (i + count <= length(sequence) && sequence(i) == sequence(i + count))
            count = count + 1;
        end

        next_sequence = strcat(next_sequence, num2str(count), sequence(i));
        i = i + count;
    end
end
