```R
look_and_say <- function(n) {
  res <- "1"
  for (i in 2:n) {
    res <- paste0(rle(strsplit(res, "")[[1]])$values, collapse = "")
    res <- gsub("(.)\\1*", function(x) paste0(nchar(x), substr(x, 1, 1)), res)
  }
  return(res)
}

# Test function
for (i in 1:8) {
  print(look_and_say(i))
}
```

