function isPrime(num) {
    for (let i = 2, s = Math.sqrt(num); i <= s; i++) {
        if (num % i === 0) return false;
    }
    return num > 1;
}

function findSequence(count) {
    let sequence = [];
    for (let i = 2; sequence.length < count; i++) {
        if (isPrime(i) && isPrime(i + 6)) {
            sequence.push(i);
            sequence.push(i + 6);
            i += 6;
        }
    }
    return sequence.slice(0, count);
}

console.log(findSequence(12));
