```javascript
function isPrime(num) {
    for (let i = 2, s = Math.sqrt(num); i <= s; i++)
        if (num % i === 0) return false;
    return num > 1;
}

function findSequence(count) {
    let sequence = [];
    let num = 2;
    while (sequence.length < count) {
        let sum = sequence.reduce((a, b) => a + b, 0) + 1;
        if (isPrime(sum) && !sequence.includes(sum)) {
            sequence.push(sum);
        } else {
            while (true) {
                num++;
                if (isPrime(num) && !sequence.includes(num)) {
                    sequence.push(num);
                    break;
                }
            }
        }
    }
    return sequence;
}

console.log(findSequence(12));
```

