function sequence(n) {
  if (n === 1) return 6;
  if (n === 2) return 7;
  if (n % 2 === 1) {
    return sequence(n - 1) * sequence(n - 2);
  } else {
    return sequence(n - 1) + sequence(n - 2);
  }
}

