function generateSequence(n) {
    let sequence = [];
    for (let i = 1; i <= n; i++) {
        let term;
        if (i % 2 === 0) {
            term = i * (i + 1) * (i + 2);
        } else {
            term = i + (i - 1) * (i + 1);
        }
        sequence.push(term);
    }
    return sequence;
}

console.log(generateSequence(11));
```

